cce36bff808a40c"], ["7qCAVkHWZkF44OzOUKf8Cr", "El Perdón (with Enrique Iglesias)", "Nicky Jam, Enrique Iglesias", "ab67616d00001e02b242b4213fb5c21d97dbbf4d"], ["5fwSHlTEWpluwOM0Sxnh5k", "Pepas", "Farruko", "ab67616d00001e023e3957dcca26c5f4ecf015ad"], ["4Ol5zkXC0ouCecmLmTK6Xb", "Ginza", "J Balvin", "ab67616d00001e021757808c95918990ef77e192"], ["5adqS3stLaSPAEOszOnpXG", "DUELE EL CORAZON", "Enrique Iglesias, Wisin", "ab67616d00001e0221d546b7511792c3aa5b7eee"], ["1RouRzlg8OKFeqc6LvdxmB", "Felices los 4", "Maluma", "ab67616d00001e0295a2cf9262058fff7dfe3674"], ["5cepAtqnEQ6yVG6088zMMu", "Corazón (feat. Nego do Borel)", "Maluma, Nego do Borel", "ab67616d00001e0295a2cf9262058fff7dfe3674"], ["3X5M53Xi5k1SijRtZMM3TA", "Te Boté - Remix", "Nio Garcia, Casper Magico, Bad Bunny, Darell, Ozuna, Nicky Jam", "ab67616d00001e02d7097c9ef004af43f08713d5"]]}]$J$::jsonb;
  p jsonb; pid uuid; k int := 0;
begin
  for p in select * from jsonb_array_elements(doc) loop
    k := k + 1;
    insert into public.playlists (company_id, kind, title, purpose, status, spotify_playlist_id, synced_at, created_by, created_at)
    values (c, 'editorial', p->>'name', p->>'purpose', 'published', p->>'id', now(), adm, now() - make_interval(mins => 100 - k))
    on conflict (company_id, spotify_playlist_id) do update set title = excluded.title, purpose = excluded.purpose
    returning id into pid;
    insert into public.artists (company_id, name) select distinct c, x->>2 from jsonb_array_elements(p->'t') x on conflict (company_id, name) do nothing;
    insert into public.music_tracks (company_id, title, artist_id, provider, provider_track_id, external_url, artwork_url, rights_status, status)
    select c, x->>1, ar.id, 'spotify', x->>0, 'https://open.spotify.com/track/' || (x->>0), case when x->>3 is not null then 'https://i.scdn.co/image/' || (x->>3) end, 'metadata_only', 'published'
    from jsonb_array_elements(p->'t') x join public.artists ar on ar.company_id = c and ar.name = x->>2
    on conflict (company_id, provider, provider_track_id) do update set artwork_url = excluded.artwork_url;
    delete from public.playlist_tracks where playlist_id = pid;
    insert into public.playlist_tracks (playlist_id, track_id, position)
    select pid, mt.id, (min(o) - 1)::int from jsonb_array_elements(p->'t') with ordinality as e(x, o)
    join public.music_tracks mt on mt.company_id = c and mt.provider = 'spotify' and mt.provider_track_id = x->>0
    group by mt.id;
  end loop;
end $do$;
